from __future__ import annotations


def operator_llm_audit_document() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ferro · LLM 请求审计</title><style>
:root{color-scheme:dark;--bg:#0a0d10;--panel:#10151a;--line:#28333c;--text:#edf2f6;--muted:#91a0ad;--ok:#8ee1b2;--bad:#ffaaa7}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,sans-serif}.shell{width:min(1180px,calc(100% - 24px));margin:auto}.top{position:sticky;top:0;background:rgba(10,13,16,.95);border-bottom:1px solid var(--line);z-index:4}.topin{min-height:58px;display:flex;align-items:center;gap:10px}.topin strong{flex:1}a,button{color:var(--text);border:1px solid #34414c;border-radius:9px;padding:8px 11px;text-decoration:none;background:#182027;font:inherit;cursor:pointer}.head{padding:20px 0 10px}.head h1{margin:0;font-size:26px}.head p{color:var(--muted);margin:6px 0}.bar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0 14px}.bar span{color:var(--muted);font-size:12px}.list{display:grid;gap:9px;padding-bottom:40px}.row{border:1px solid var(--line);border-radius:12px;background:var(--panel);padding:12px}.meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12px}.meta b{margin-right:auto}.ok{color:var(--ok)}.bad{color:var(--bad)}.muted{color:var(--muted)}.ctx{margin-top:8px;color:#c8d2da;font-size:12px;line-height:1.55}.ctx .issue{color:var(--bad)}.ctx code{color:#dbe8f0}details{margin-top:9px;border-top:1px solid #232c34;padding-top:8px}summary{cursor:pointer;color:#c8d2da}pre{white-space:pre-wrap;word-break:break-word;background:#090d11;border:1px solid #232c34;border-radius:8px;padding:10px;max-height:360px;overflow:auto;font-size:11px;line-height:1.45}.empty{color:var(--muted);padding:20px 0}@media(max-width:620px){.shell{width:calc(100% - 14px)}.topin{flex-wrap:wrap;padding:8px 0}.topin strong{width:100%;flex-basis:100%}.head{padding-top:14px}}
</style></head><body><header class="top"><div class="shell topin"><strong>Ferro · LLM 请求审计</strong><a href="/operator/">管理后台</a><a href="/operator/chat/">私人对话</a></div></header>
<main class="shell"><div class="head"><h1>大模型调用记录</h1><p>记录每次请求的提示、响应、耗时、模型/Provider 与错误。密钥和常见凭据会在落盘前脱敏；原始调用日志达到保留上限后滚动，长期记忆不在这里删除。</p></div>
<div class="bar"><button id="refresh">刷新</button><span id="summary">正在读取…</span></div><div id="list" class="list"></div></main>
<script>(()=>{const $=id=>document.getElementById(id);const esc=v=>String(v??'');function pre(title,text){const d=document.createElement('details'),s=document.createElement('summary'),p=document.createElement('pre');s.textContent=title;p.textContent=esc(text);d.append(s,p);return d}
function render(rows){const root=$('list');root.innerHTML='';const providerFails=rows.filter(r=>r.failure_domain==='PROVIDER_AVAILABILITY'||r.failure_domain==='PROVIDER_TIMEOUT').length;const contextIssues=rows.filter(r=>(((r.context_audit||{}).diagnostics||{}).issues||[]).length).length;$('summary').textContent='最近 '+rows.length+' 次调用 · Provider '+providerFails+' 个失败 · Context '+contextIssues+' 个告警';if(!rows.length){const e=document.createElement('div');e.className='empty';e.textContent='还没有 LLM 调用记录。';root.append(e);return}for(const r of rows){const c=document.createElement('article');c.className='row';const m=document.createElement('div');m.className='meta';const title=document.createElement('b');const provider=r.provider||{};title.textContent=(provider.model||provider.model_name||provider.class||'LLM')+' · '+(r.scope||'content-agent');const status=document.createElement('span');status.className=r.status==='OK'?'ok':'bad';status.textContent=r.status||'UNKNOWN';const time=document.createElement('span');time.className='muted';const route=(r.routing||{}).selected_resource_id;const first=r.first_token_ms==null?'':' · 首字 '+esc(r.first_token_ms)+' ms';time.textContent=(r.started_at?new Date(r.started_at).toLocaleString():'')+' · 总 '+esc(r.latency_ms)+' ms'+first+(route?' · '+route:'');m.append(title,status,time);c.append(m);const ca=r.context_audit||{},diag=ca.diagnostics||{},df=ca.decision_frame||{},receipt=ca.context_receipt||{};if(r.failure_domain||Object.keys(ca).length){const x=document.createElement('div');x.className='ctx';const bits=[];if(r.failure_domain)bits.push('失败域 '+r.failure_domain);if(df.decision_type)bits.push('决策 '+df.decision_type);if(diag.prompt_chars!=null)bits.push('Prompt '+diag.prompt_chars+' chars');if(diag.budget_utilization_estimate!=null)bits.push('Context预算 '+Math.round(diag.budget_utilization_estimate*100)+'%');if(r.context_receipt_id)bits.push('Receipt '+String(r.context_receipt_id).slice(-12));x.textContent=bits.join(' · ');const issues=diag.issues||[];if(issues.length){const w=document.createElement('div');w.className='issue';w.textContent='Context告警: '+issues.join(', ');x.append(w)}c.append(x)}if(r.error){const e=document.createElement('div');e.className='bad';e.textContent=(r.failure_domain?('['+r.failure_domain+'] '):'')+esc(r.error_type)+': '+esc(r.error);c.append(e)}if(Object.keys(ca).length)c.append(pre('Context receipt / diagnosis',JSON.stringify(ca,null,2)));c.append(pre('System prompt',r.system||''),pre('Request prompt',r.prompt||''));if('response'in r)c.append(pre('Response',r.response||''));root.append(c)}}
async function load(){try{const r=await fetch('/operator/api/llm-requests?limit=200',{cache:'no-store',headers:{'x-operator-request':'1'}});if(r.status===401){location.href='/operator/';return}const d=await r.json();if(!r.ok)throw new Error(d.error||('HTTP '+r.status));render(d.requests||[])}catch(e){$('summary').textContent=e.message}}
$('refresh').onclick=load;load();})();</script></body></html>'''


__all__ = ["operator_llm_audit_document"]
